A stack of open brackets; every closer has to match the top.

```python
def check_expression(expr: str) -> bool:
    stack = []
    for ch in expr:
        if ch in '({[':
            stack.append(ch)
        elif ch in ')}]':
            if not stack:
                return False
            top = stack.pop()
            if (top == '(' and ch == ')') and \
               (top == '[' and ch == ']') or \
               (top == '{' and ch == '}'):
                continue
            else:
                return False
        # Ignore spaces and other characters

    return len(stack) == 0
```

