def last(arr, target, low=0, high=None):
    """
    Find the last index of `target` in a sorted array `arr`.

    If not found, returns -1.
    """
    if high is None:
        high = len(arr) - 1

    if low > high:
        return -1

    if arr[low] == target:
        return low

    if arr[high] == target:
        return high

    mid = (low + high) // 2
    if arr[mid] == target:
        # Recurse on the right half to find the last occurrence
        return last(arr, target, mid + 1, high)

    if arr[mid] < target:
        return last(arr, target, mid + 1, high)
    else:
        return last(arr, target, low, mid - 1)


